<template><div class="page"><header><div><h2>Fondos y Control de Caja</h2><p>Fondos autorizados, custodia y expedientes derivados de arqueos; no modifica la caja física.</p></div><div class="filters"><label>Finca<select v-model="fincaId" @change="cargar"><option value="">Seleccione</option><option v-for="f in fincas" :key="f.id" :value="f.id">{{f.code}} - {{f.name}}</option></select></label><label>Año<input v-model.number="anio" type="number" @change="tablero" /></label><label>Mes<select v-model.number="mes" @change="tablero"><option v-for="(_,i) in meses" :key="i" :value="i+1">{{meses[i]}}</option></select></label></div></header>
<section class="card"><h3>Tablero de cumplimiento</h3><div v-if="!fincaId" class="empty">Seleccione una finca.</div><div v-else class="metrics"><article :class="{alerta:!data.cumplimientoArqueoMensual}"><span>Arqueo mensual</span><strong>{{data.cumplimientoArqueoMensual?'Cumplido':'Pendiente'}}</strong><small>{{data.arqueosCerrados||0}} cerrados · {{data.arqueosAbiertos||0}} abiertos</small></article><article :class="{alerta:data.depositoPendiente}"><span>Saldo por depositar</span><strong>{{moneda(data.saldoPorDepositar||0)}}</strong><small>{{data.depositoPendiente?'Depósito pendiente':'Sin pendiente'}}</small></article><article><span>Incidencias pendientes</span><strong>{{data.incidenciasPendientes||0}}</strong><small>Expedientes por resolver</small></article><article><span>Fondos autorizados</span><strong>{{moneda(totalFondos)}}</strong><small>Cambio {{moneda(data.fondoCambioAutorizado||0)}} · Pagos {{moneda(data.fondoPagosMenoresAutorizado||0)}}</small></article></div></section>
<section class="card"><div class="title"><div><h3>Fondos autorizados</h3><p>Guardar actualiza el tipo de fondo para la finca.</p></div><button class="primary" :disabled="!fincaId" @click="mostrarFondo=!mostrarFondo">Configurar</button></div><form v-if="mostrarFondo" @submit.prevent="guardarFondo"><label>Tipo<select v-model="fondo.tipo"><option value="CAMBIO">Cambio</option><option value="PAGOS_MENORES">Pagos menores</option><option value="NOMINA">Nómina</option><option value="POR_DEPOSITAR">Por depositar</option></select></label><label>Importe autorizado<input v-model.number="fondo.importeAutorizado" type="number" min="0" step="0.01" /></label><label>Activo<select v-model="fondo.activo"><option :value="true">Sí</option><option :value="false">No</option></select></label><label class="wide">Observaciones<input v-model.trim="fondo.observaciones" maxlength="300" /></label><div class="actions"><button class="primary" :disabled="guardando">Guardar fondo</button></div></form><div class="wrap"><table><thead><tr><th>Tipo</th><th>Autorizado</th><th>Activo</th><th>Observaciones</th></tr></thead><tbody><tr v-for="f in fondos" :key="f.id"><td>{{etiqueta(f.tipo)}}</td><td class="money">{{moneda(f.importeAutorizado)}}</td><td>{{f.activo?'Sí':'No'}}</td><td>{{f.observaciones||'—'}}</td></tr></tbody></table></div></section>
<section class="card"><div class="title"><div><h3>Actas de responsabilidad</h3><p>Una custodia activa por finca.</p></div><button class="primary" :disabled="!fincaId" @click="mostrarActa=!mostrarActa">Nueva acta</button></div><form v-if="mostrarActa" @submit.prevent="guardarActa"><label>Nombre del custodio<input v-model.trim="acta.custodioNombre" required /></label><label>ID del custodio<input v-model.trim="acta.custodioId" placeholder="Opcional" /></label><label class="wide">Observaciones<input v-model.trim="acta.observaciones" /></label><div class="actions"><button class="primary">Registrar acta</button></div></form><div class="wrap"><table><thead><tr><th>No.</th><th>Custodio</th><th>Inicio</th><th>Cierre</th><th>Estado</th><th>Observaciones</th><th></th></tr></thead><tbody><tr v-for="a in actas" :key="a.id"><td>{{a.numero||'—'}}</td><td>{{a.custodioNombre}}</td><td>{{fecha(a.fechaInicio)}}</td><td>{{fecha(a.fechaCierre)}}</td><td>{{a.estado}}</td><td>{{a.observaciones||'—'}}</td><td><button v-if="a.estado==='ACTIVA'" class="link danger" @click="cerrarActa(a)">Cerrar</button></td></tr></tbody></table></div></section>
<section class="card"><div class="title"><div><h3>Expedientes de diferencias</h3><p>Tipo e importe se determinan desde el arqueo cerrado con diferencia.</p></div><button class="primary" :disabled="!fincaId" @click="mostrarIncidencia=!mostrarIncidencia">Abrir expediente</button></div><form v-if="mostrarIncidencia" @submit.prevent="guardarIncidencia"><label>ID del arqueo<input v-model.trim="incidencia.arqueoCajaId" required /></label><label>Expediente<input v-model.trim="incidencia.expediente" required /></label><label class="wide">Descripción<input v-model.trim="incidencia.descripcion" required /></label><div class="actions"><button class="primary">Crear</button></div></form><div class="wrap"><table><thead><tr><th>Fecha</th><th>Expediente</th><th>Tipo</th><th>Importe</th><th>Estado</th><th>Descripción / observación</th><th></th></tr></thead><tbody><tr v-for="i in incidencias" :key="i.id"><td>{{fecha(i.fechaCreacion)}}</td><td>{{i.expediente}}</td><td>{{i.tipo}}</td><td class="money">{{moneda(i.importe)}}</td><td>{{i.estado}}</td><td>{{i.observaciones||i.descripcion}}</td><td><button v-if="i.estado==='PENDIENTE'" class="link" @click="actualizar(i,'EN_REVISION')">Revisar</button><button v-if="!['RESUELTA','RECHAZADA'].includes(i.estado)" class="link success" @click="resolver(i)">Resolver</button></td></tr></tbody></table></div></section></div></template>
<script setup lang="ts">import{computed,onMounted,reactive,ref}from'vue';import{notify}from'@/composables/useNotification';import FincaService from'@/services/FincaService';import CajaOficialService,{type FondoCaja,type FondoCajaRequest,type IncidenciaArqueo,type IncidenciaArqueoRequest,type ResponsabilidadCaja,type ResponsabilidadCajaRequest,type TableroCajaOficial}from'@/services/CajaOficialService';const n=new Date(),meses=['Enero','Febrero','Marzo','Abril','Mayo','Junio','Julio','Agosto','Septiembre','Octubre','Noviembre','Diciembre'],fincaId=ref(''),anio=ref(n.getFullYear()),mes=ref(n.getMonth()+1),fincas=ref<Array<{id:string;code:string;name:string}>>([]),fondos=ref<FondoCaja[]>([]),actas=ref<ResponsabilidadCaja[]>([]),incidencias=ref<IncidenciaArqueo[]>([]),data=ref<TableroCajaOficial>({}),mostrarFondo=ref(false),mostrarActa=ref(false),mostrarIncidencia=ref(false),guardando=ref(false);const fondo=reactive({tipo:'CAMBIO' as FondoCaja['tipo'],importeAutorizado:0,activo:true,observaciones:''}),acta=reactive({custodioId:'',custodioNombre:'',observaciones:''}),incidencia=reactive({arqueoCajaId:'',expediente:'',descripcion:''});const moneda=(x:number)=>`$${(x||0).toLocaleString('es-CU',{minimumFractionDigits:2,maximumFractionDigits:2})}`,fecha=(x?:string)=>x?new Date(x).toLocaleDateString('es-CU'):'—',etiqueta=(x:string)=>({CAMBIO:'Cambio',PAGOS_MENORES:'Pagos menores',NOMINA:'Nómina',POR_DEPOSITAR:'Por depositar'}[x]||x),totalFondos=computed(()=>fondos.value.filter(x=>x.activo).reduce((s,x)=>s+x.importeAutorizado,0));async function cargar(){if(!fincaId.value)return;try{const[a,b,c]=await Promise.all([CajaOficialService.listarFondos(fincaId.value),CajaOficialService.listarResponsabilidades(fincaId.value),CajaOficialService.listarIncidencias(fincaId.value)]);fondos.value=a.data||[];actas.value=b.data||[];incidencias.value=c.data||[];await tablero()}catch(e){console.error(e);notify.error('Error','No se pudo cargar el control oficial.')}}async function tablero(){if(!fincaId.value)return;try{data.value=(await CajaOficialService.tablero(fincaId.value,anio.value,mes.value)).data||{}}catch(e){console.error(e);notify.error('Error','No se pudo cargar el tablero.')}}async function guardarFondo(){if(!fincaId.value)return;guardando.value=true;try{const r:FondoCajaRequest={fincaId:fincaId.value,...fondo,observaciones:fondo.observaciones||undefined};await CajaOficialService.crearFondo(r);mostrarFondo.value=false;await cargar();notify.success('Fondo guardado','Autorización actualizada.')}catch(e){console.error(e);notify.error('Error','No se pudo guardar el fondo.')}finally{guardando.value=false}}async function guardarActa(){if(!fincaId.value||!acta.custodioNombre)return;try{const r:ResponsabilidadCajaRequest={fincaId:fincaId.value,custodioNombre:acta.custodioNombre,custodioId:acta.custodioId||undefined,observaciones:acta.observaciones||undefined};await CajaOficialService.crearResponsabilidad(r);mostrarActa.value=false;acta.custodioNombre='';acta.custodioId='';acta.observaciones='';await cargar();notify.success('Acta registrada','Custodia documentada.')}catch(e){console.error(e);notify.error('Error','No se pudo registrar el acta.')}}async function cerrarActa(a:ResponsabilidadCaja){const o=window.prompt('Observaciones de cierre:');if(o===null)return;try{await CajaOficialService.cerrarResponsabilidad(a.id,{observaciones:o||undefined});await cargar();notify.success('Acta cerrada','Custodia cerrada.')}catch(e){console.error(e);notify.error('Error','No se pudo cerrar el acta.')}}async function guardarIncidencia(){if(!incidencia.arqueoCajaId||!incidencia.expediente||!incidencia.descripcion)return;try{const r:IncidenciaArqueoRequest={...incidencia};await CajaOficialService.crearIncidencia(r);mostrarIncidencia.value=false;incidencia.arqueoCajaId='';incidencia.expediente='';incidencia.descripcion='';await cargar();notify.success('Expediente creado','Incidencia vinculada al arqueo.')}catch(e){console.error(e);notify.error('Error','No se pudo crear el expediente.')}}async function actualizar(i:IncidenciaArqueo,e:string,o?:string){try{await CajaOficialService.actualizarIncidencia(i.id,{estado:e,observaciones:o});await cargar();notify.success('Incidencia actualizada','Estado actualizado.')}catch(x){console.error(x);notify.error('Error','No se pudo actualizar la incidencia.')}}async function resolver(i:IncidenciaArqueo){const o=window.prompt('Resolución u observaciones:');if(!o?.trim())return;await actualizar(i,'RESUELTA',o.trim())}onMounted(async()=>{try{fincas.value=(await FincaService.buscarFincas({size:999})).data.data||[]}catch(e){console.error(e);notify.error('Error','No se pudieron cargar las fincas.')}})</script>
<style scoped>.page{max-width:1450px;margin:auto;padding:1.5rem;color:#263238}header,.title,.filters{display:flex;justify-content:space-between;gap:1rem;align-items:flex-start}h2,h3{margin:0;color:#1e3a5f}p,small{color:#64748b}.card{background:#fff;border:1px solid #dbe4ea;border-radius:10px;padding:1.25rem;margin:1.25rem 0}.filters{align-items:end}.filters label,form label{display:grid;gap:.25rem;font-size:.78rem;font-weight:600}select,input{border:1px solid #cbd5e1;border-radius:6px;padding:.52rem}.metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:.75rem;margin-top:1rem}.metrics article{border-left:4px solid #2563eb;background:#eff6ff;padding:.75rem;display:grid;gap:.25rem}.metrics article.alerta{border-color:#dc2626;background:#fff1f2}.metrics strong{font-size:1.2rem}form{display:grid;grid-template-columns:repeat(4,1fr);gap:.75rem;background:#f8fafc;padding:1rem;margin:1rem 0}.wide{grid-column:span 2}.actions{display:flex;align-items:end;justify-content:flex-end}.primary,.link{border:0;border-radius:6px;padding:.6rem 1rem;cursor:pointer;font-weight:600}.primary{background:#2563eb;color:#fff}.link{background:none;color:#2563eb;padding:.2rem}.danger{color:#b91c1c}.success{color:#15803d}.wrap{overflow:auto}table{width:100%;min-width:800px;border-collapse:collapse}th,td{border-bottom:1px solid #e2e8f0;padding:.6rem;text-align:left}th{background:#f1f5f9;font-size:.72rem}.money{text-align:right;font-weight:600}.empty{text-align:center;padding:1.5rem}@media(max-width:900px){header,.title,.filters{flex-direction:column}.metrics,form{grid-template-columns:1fr 1fr}}@media(max-width:550px){.metrics,form{grid-template-columns:1fr}.wide{grid-column:span 1}}</style>
